    72→		return nil, fmt.Errorf("invalid deposit requests SSZ size, got %d expected at least %d", len(requestListInSSZBytes), drSize)
    73→	}
    74→	maxSSZsize := uint64(drSize) * maxDepositRequests
    75→	if uint64(len(requestListInSSZBytes)) > maxSSZsize {
    76→		return nil, fmt.Errorf("invalid deposit requests SSZ size, requests should not be more than the max per payload, got %d max %d", len(requestListInSSZBytes), maxSSZsize)
    77→	}
