   103→func decodeExecutionRequest(req []byte) (typ uint8, data []byte, err error) {
   104→	if len(req) < 1 {
   105→		return 0, nil, errors.New("invalid execution request, length less than 1")
   106→	}
   107→	return req[0], req[1:], nil
