   554→func (s *Service) processChainStartIfReady(ctx context.Context, blockHash [32]byte, blockNumber *big.Int, blockTime uint64) {
   555→	valCount, genesisTime := s.currentCountAndTime(ctx, blockTime)
   556→	if valCount == 0 {
   557→		return
   558→	}
   559→	triggered := coreState.IsValidGenesisState(valCount, genesisTime)
   560→	if triggered {
   561→		s.chainStartData.GenesisTime = genesisTime
   562→		s.ProcessChainStart(s.chainStartData.GenesisTime, blockHash, blockNumber)
   563→	}
