    96→// Forces to retry an execution client connection.
    97→func (s *Service) retryExecutionClientConnection(ctx context.Context, err error) {
    98→	s.runError = errors.Wrap(err, "retryExecutionClientConnection")
    99→	s.updateConnectedETH1(false)
   100→	// Back off for a while before redialing.
   101→	time.Sleep(backOffPeriod)
   102→	currClient := s.rpcClient
   103→	if err := s.setupExecutionClientConnections(ctx, s.cfg.currHttpEndpoint); err != nil {
   104→		s.runError = errors.Wrap(err, "setupExecutionClientConnections")
   105→		return
   106→	}
   107→	// Close previous client, if connection was successful.
   108→	if currClient != nil {
