    23→
    24→// AuthorizationData holds all information necessary to authorize with HTTP.
    25→type AuthorizationData struct {
    26→	Method authorization.Method
    27→	Value  string
    28→	JwtId  string
    29→}
    30→
    31→// Equals compares two endpoints for equality.
