    34→}
    35→
    36→// HttpClient creates a http client object dependent
    37→// on the properties of the network endpoint.
    38→func (e Endpoint) HttpClient() *http.Client {
    39→	if e.Auth.Method != authorization.Bearer {
    40→		return &http.Client{Transport: otelhttp.NewTransport(http.DefaultTransport)}
    41→	}
    42→	return NewHttpClientWithSecret(e.Auth.Value, e.Auth.JwtId)
    43→}
    44→
    45→// Equals compares two authorization data objects for equality.
    46→func (d *AuthorizationData) Equals(other AuthorizationData) bool {
    47→	return d.Method == other.Method && d.Value == other.Value
    48→}
