    64→// HttpEndpoint extracts an httputils.Endpoint from the provider parameter.
    65→func HttpEndpoint(eth1Provider string) Endpoint {
    66→	endpoint := Endpoint{
    67→		Url: "",
    68→		Auth: AuthorizationData{
    69→			Method: authorization.None,
    70→			Value:  "",
    71→		}}
    72→
    73→	authValues := strings.Split(eth1Provider, ",")
    74→	endpoint.Url = strings.TrimSpace(authValues[0])
    75→	if len(authValues) > 2 {
    76→		log.Errorf(
    77→			"ETH1 endpoint string can contain one comma for specifying the authorization header to access the provider."+
    78→				" String contains too many commas: %d. Skipping authorization.", len(authValues)-1)
    79→	} else if len(authValues) == 2 {
    80→		switch Method(strings.TrimSpace(authValues[1])) {
    81→		case authorization.Basic:
    82→			basicAuthValues := strings.Split(strings.TrimSpace(authValues[1]), " ")
    83→			if len(basicAuthValues) != 2 {
    84→				log.Errorf("Basic Authentication has incorrect format. Skipping authorization.")
    85→			} else {
    86→				endpoint.Auth.Method = authorization.Basic
    87→				endpoint.Auth.Value = base64.StdEncoding.EncodeToString([]byte(basicAuthValues[1]))
    88→			}
    89→		case authorization.Bearer:
    90→			bearerAuthValues := strings.Split(strings.TrimSpace(authValues[1]), " ")
    91→			if len(bearerAuthValues) != 2 {
    92→				log.Errorf("Bearer Authentication has incorrect format. Skipping authorization.")
    93→			} else {
    94→				endpoint.Auth.Method = authorization.Bearer
    95→				endpoint.Auth.Value = bearerAuthValues[1]
    96→			}
    97→		case authorization.None:
    98→			log.Errorf("Authorization has incorrect format or authorization type is not supported.")
    99→		}
   100→	}
   101→	return endpoint
   102→}
