   104→// Method returns the authorizationmethod.AuthorizationMethod corresponding with the parameter value.
   105→func Method(auth string) authorization.Method {
   106→	if strings.HasPrefix(strings.ToLower(auth), "basic") {
   107→		return authorization.Basic
   108→	}
   109→	if strings.HasPrefix(strings.ToLower(auth), "bearer") {
   110→		return authorization.Bearer
   111→	}
   112→	return authorization.None
   113→}
