   115→// NewHttpClientWithSecret returns a http client that utilizes
   116→// jwt authentication.
   117→func NewHttpClientWithSecret(secret, id string) *http.Client {
   118→	authTransport := &jwtTransport{
   119→		underlyingTransport: http.DefaultTransport,
   120→		jwtSecret:           []byte(secret),
   121→		jwtId:               id,
   122→	}
   123→	return &http.Client{
   124→		Timeout:   DefaultRPCHTTPTimeout,
   125→		Transport: otelhttp.NewTransport(authTransport),
   126→	}
   127→}
