   129→func NewExecutionRPCClient(ctx context.Context, endpoint Endpoint, headers http.Header) (*gethRPC.Client, error) {
   130→	// Need to handle ipc and http
   131→	var client *gethRPC.Client
   132→	u, err := url.Parse(endpoint.Url)
   133→	if err != nil {
   134→		return nil, err
   135→	}
   136→	switch u.Scheme {
   137→	case "http", "https":
   138→		client, err = gethRPC.DialOptions(ctx, endpoint.Url, gethRPC.WithHTTPClient(endpoint.HttpClient()), gethRPC.WithHeaders(headers))
   139→		if err != nil {
   140→			return nil, err
   141→		}
   142→	case "", "ipc":
   143→		client, err = gethRPC.DialIPC(ctx, endpoint.Url)
   144→		if err != nil {
   145→			return nil, err
   146→		}
   147→	default:
   148→		return nil, fmt.Errorf("no known transport for URL scheme %q", u.Scheme)
   149→	}
   150→	return client, nil
   151→}
