    35→	changes, err := b.Body().BLSToExecutionChanges()
    36→	if err != nil {
    37→		return nil, errors.Wrap(err, "could not get BLSToExecutionChanges")
    38→	}
    39→	// Return early if no changes
    40→	if len(changes) == 0 {
    41→		return st, nil
    42→	}
    43→	for _, change := range changes {
    44→		st, err = processBLSToExecutionChange(st, change)
    45→		if err != nil {
    46→			return nil, errors.Wrap(err, "could not process BLSToExecutionChange")
    47→		}
    48→	}
    49→	return st, nil
    50→}
