    52→// processBLSToExecutionChange validates a SignedBLSToExecution message and
    53→// changes the validator's withdrawal address accordingly.
    54→//
    55→// Spec pseudocode definition:
    56→//
    57→// def process_bls_to_execution_change(state: BeaconState, signed_address_change: SignedBLSToExecutionChange) -> None:
    58→//
    59→//	validator = state.validators[address_change.validator_index]
    60→//
    61→//	assert validator.withdrawal_credentials[:1] == BLS_WITHDRAWAL_PREFIX
    62→//	assert validator.withdrawal_credentials[1:] == hash(address_change.from_bls_pubkey)[1:]
    63→//
    64→//	domain = get_domain(state, DOMAIN_BLS_TO_EXECUTION_CHANGE)
    65→//	signing_root = compute_signing_root(address_change, domain)
    66→//	assert bls.Verify(address_change.from_bls_pubkey, signing_root, signed_address_change.signature)
    67→//
    68→//	validator.withdrawal_credentials = (
    69→//	    ETH1_ADDRESS_WITHDRAWAL_PREFIX
    70→//	    + b'\x00' * 11
    71→//	    + address_change.to_execution_address
    72→//	)
    73→func processBLSToExecutionChange(st state.BeaconState, signed *ethpb.SignedBLSToExecutionChange) (state.BeaconState, error) {
    74→	// Checks that the message passes the validation conditions.
    75→	val, err := ValidateBLSToExecutionChange(st, signed)
    76→	if err != nil {
    77→		return nil, err
    78→	}
    79→
    80→	message := signed.Message
    81→	newCredentials := make([]byte, executionToBLSPadding)
    82→	newCredentials[0] = params.BeaconConfig().ETH1AddressWithdrawalPrefixByte
    83→	val.WithdrawalCredentials = append(newCredentials, message.ToExecutionAddress...)
    84→	err = st.UpdateValidatorAtIndex(message.ValidatorIndex, val)
    85→	return st, err
    86→}
