    88→// ValidateBLSToExecutionChange validates the execution change message against the state and returns the
    89→// validator referenced by the message.
    90→func ValidateBLSToExecutionChange(st state.ReadOnlyBeaconState, signed *ethpb.SignedBLSToExecutionChange) (*ethpb.Validator, error) {
    91→	if signed == nil {
    92→		return nil, errNilSignedWithdrawalMessage
    93→	}
    94→	message := signed.Message
    95→	if message == nil {
    96→		return nil, errNilWithdrawalMessage
    97→	}
    98→
    99→	val, err := st.ValidatorAtIndex(message.ValidatorIndex)
   100→	if err != nil {
   101→		return nil, err
   102→	}
   103→	if val == nil {
   104→		return nil, errors.Wrap(errInvalidWithdrawalCredentials, "validator is nil") // This should not be possible.
   105→	}
   106→	cred := val.WithdrawalCredentials
   107→	if len(cred) < 2 || cred[0] != params.BeaconConfig().BLSWithdrawalPrefixByte {
   108→		return nil, errInvalidBLSPrefix
   109→	}
   110→
   111→	// hash the public key and verify it matches the withdrawal credentials
   112→	fromPubkey := message.FromBlsPubkey
   113→	hashFn := ssz.NewHasherFunc(hash.CustomSHA256Hasher())
   114→	digest := hashFn.Hash(fromPubkey)
   115→	if !bytes.Equal(digest[1:], cred[1:]) {
   116→		return nil, errInvalidWithdrawalCredentials
   117→	}
   118→	return val, nil
   119→}
