   122→// into the beacon state.
   123→//
   124→// Spec pseudocode definition:
   125→//
   126→// def process_withdrawals(state: BeaconState, payload: ExecutionPayload) -> None:
   127→//
   128→//	expected_withdrawals, processed_partial_withdrawals_count = get_expected_withdrawals(state) # [Modified in Electra:EIP7251]
