   136→//	# Update pending partial withdrawals [New in Electra:EIP7251]
   137→//	state.pending_partial_withdrawals = state.pending_partial_withdrawals[processed_partial_withdrawals_count:]
   138→//
   139→//	# Update the next withdrawal index if this block contained withdrawals
   140→//	if len(expected_withdrawals) != 0:
   141→//	    latest_withdrawal = expected_withdrawals[-1]
   142→//	    state.next_withdrawal_index = WithdrawalIndex(latest_withdrawal.index + 1)
   143→//
   144→//	# Update the next validator index to start the next withdrawal sweep
   145→//	if len(expected_withdrawals) == MAX_WITHDRAWALS_PER_PAYLOAD:
   146→//	    # Next sweep starts after the latest withdrawal's validator index
   147→//	    next_validator_index = ValidatorIndex((expected_withdrawals[-1].validator_index + 1) % len(state.validators))
   148→//	    state.next_withdrawal_validator_index = next_validator_index
   149→//	else:
   150→//	    # Advance sweep by the max length of the sweep if there was not a full set of withdrawals
   151→//	    next_index = state.next_withdrawal_validator_index + MAX_VALIDATORS_PER_WITHDRAWALS_SWEEP
   152→//	    next_validator_index = ValidatorIndex(next_index % len(state.validators))
   153→//	    state.next_withdrawal_validator_index = next_validator_index
   154→func ProcessWithdrawals(st state.BeaconState, executionData interfaces.ExecutionData) (state.BeaconState, error) {
   155→	expectedWithdrawals, processedPartialWithdrawalsCount, err := st.ExpectedWithdrawals()
   156→	if err != nil {
   157→		return nil, errors.Wrap(err, "could not get expected withdrawals")
   158→	}
   159→
   160→	var wdRoot [32]byte
   161→	if executionData.IsBlinded() {
   162→		r, err := executionData.WithdrawalsRoot()
   163→		if err != nil {
   164→			return nil, errors.Wrap(err, "could not get withdrawals root")
   165→		}
   166→		wdRoot = bytesutil.ToBytes32(r)
   167→	} else {
   168→		wds, err := executionData.Withdrawals()
   169→		if err != nil {
   170→			return nil, errors.Wrap(err, "could not get withdrawals")
   171→		}
   172→
   173→		if len(wds) != len(expectedWithdrawals) {
   174→			return nil, fmt.Errorf("execution payload header has %d withdrawals when %d were expected", len(wds), len(expectedWithdrawals))
   175→		}
   176→
   177→		wdRoot, err = ssz.WithdrawalSliceRoot(wds, fieldparams.MaxWithdrawalsPerPayload)
   178→		if err != nil {
   179→			return nil, errors.Wrap(err, "could not get withdrawals root")
   180→		}
   181→	}
   182→
   183→	expectedRoot, err := ssz.WithdrawalSliceRoot(expectedWithdrawals, fieldparams.MaxWithdrawalsPerPayload)
   184→	if err != nil {
   185→		return nil, errors.Wrap(err, "could not get expected withdrawals root")
   186→	}
   187→	if expectedRoot != wdRoot {
   188→		return nil, fmt.Errorf("expected withdrawals root %#x, got %#x", expectedRoot, wdRoot)
   189→	}
   190→
   191→	for _, withdrawal := range expectedWithdrawals {
   192→		err := helpers.DecreaseBalance(st, withdrawal.ValidatorIndex, withdrawal.Amount)
   193→		if err != nil {
   194→			return nil, errors.Wrap(err, "could not decrease balance")
   195→		}
   196→	}
   197→
   198→	if st.Version() >= version.Electra {
   199→		if err := st.DequeuePendingPartialWithdrawals(processedPartialWithdrawalsCount); err != nil {
   200→			return nil, fmt.Errorf("unable to dequeue partial withdrawals from state: %w", err)
   201→		}
   202→	}
   203→
   204→	if len(expectedWithdrawals) > 0 {
   205→		if err := st.SetNextWithdrawalIndex(expectedWithdrawals[len(expectedWithdrawals)-1].Index + 1); err != nil {
   206→			return nil, errors.Wrap(err, "could not set next withdrawal index")
   207→		}
   208→	}
   209→	var nextValidatorIndex primitives.ValidatorIndex
   210→	if uint64(len(expectedWithdrawals)) < params.BeaconConfig().MaxWithdrawalsPerPayload {
   211→		nextValidatorIndex, err = st.NextWithdrawalValidatorIndex()
   212→		if err != nil {
   213→			return nil, errors.Wrap(err, "could not get next withdrawal validator index")
   214→		}
   215→		nextValidatorIndex += primitives.ValidatorIndex(params.BeaconConfig().MaxValidatorsPerWithdrawalsSweep)
   216→		nextValidatorIndex = nextValidatorIndex % primitives.ValidatorIndex(st.NumValidators())
   217→	} else {
   218→		nextValidatorIndex = expectedWithdrawals[len(expectedWithdrawals)-1].ValidatorIndex + 1
   219→		if nextValidatorIndex == primitives.ValidatorIndex(st.NumValidators()) {
   220→			nextValidatorIndex = 0
   221→		}
   222→	}
   223→	if err := st.SetNextWithdrawalValidatorIndex(nextValidatorIndex); err != nil {
   224→		return nil, errors.Wrap(err, "could not set next withdrawal validator index")
   225→	}
   226→	return st, nil
   227→}
