   229→// BLSChangesSignatureBatch extracts the relevant signatures from the provided execution change
   230→// messages and transforms them into a signature batch object.
   231→func BLSChangesSignatureBatch(
   232→	st state.ReadOnlyBeaconState,
   233→	changes []*ethpb.SignedBLSToExecutionChange,
   234→) (*bls.SignatureBatch, error) {
   235→	// Return early if no changes
   236→	if len(changes) == 0 {
   237→		return bls.NewSet(), nil
   238→	}
   239→	batch := &bls.SignatureBatch{
   240→		Signatures:   make([][]byte, len(changes)),
   241→		PublicKeys:   make([]bls.PublicKey, len(changes)),
   242→		Messages:     make([][32]byte, len(changes)),
   243→		Descriptions: make([]string, len(changes)),
   244→	}
   245→	c := params.BeaconConfig()
   246→	domain, err := signing.ComputeDomain(c.DomainBLSToExecutionChange, c.GenesisForkVersion, st.GenesisValidatorsRoot())
   247→	if err != nil {
   248→		return nil, errors.Wrap(err, "could not compute signing domain")
   249→	}
   250→	for i, change := range changes {
   251→		batch.Signatures[i] = change.Signature
   252→		publicKey, err := bls.PublicKeyFromBytes(change.Message.FromBlsPubkey)
   253→		if err != nil {
   254→			return nil, errors.Wrap(err, "could not convert bytes to public key")
   255→		}
   256→		batch.PublicKeys[i] = publicKey
   257→		htr, err := signing.Data(change.Message.HashTreeRoot, domain)
   258→		if err != nil {
   259→			return nil, errors.Wrap(err, "could not compute BLSToExecutionChange signing data")
   260→		}
   261→		batch.Messages[i] = htr
   262→		batch.Descriptions[i] = signing.BlsChangeSignature
   263→	}
   264→	return batch, nil
   265→}
   266→
   267→// VerifyBLSChangeSignature checks the signature in the SignedBLSToExecutionChange message.
   268→// It validates the signature with the Capella fork version if the passed state
   269→// is from a previous fork.
   270→func VerifyBLSChangeSignature(
   271→	st state.ReadOnlyBeaconState,
   272→	change *ethpb.SignedBLSToExecutionChange,
   273→) error {
   274→	c := params.BeaconConfig()
   275→	domain, err := signing.ComputeDomain(c.DomainBLSToExecutionChange, c.GenesisForkVersion, st.GenesisValidatorsRoot())
   276→	if err != nil {
   277→		return errors.Wrap(err, "could not compute signing domain")
   278→	}
   279→	publicKey := change.Message.FromBlsPubkey
   280→	return signing.VerifySigningRoot(change.Message, publicKey, change.Signature, domain)
   281→}
