   147→// ValidatePayload validates if payload is valid versus input beacon state.
   148→// These validation steps apply to both pre merge and post merge.
   149→//
   150→// Spec code:
   151→//
   152→//	# Verify random
   153→//	assert payload.random == get_randao_mix(state, get_current_epoch(state))
   154→//	# Verify timestamp
   155→//	assert payload.timestamp == compute_timestamp_at_slot(state, state.slot)
   156→func ValidatePayload(st state.BeaconState, payload interfaces.ExecutionData) error {
   157→	random, err := helpers.RandaoMix(st, time.CurrentEpoch(st))
   158→	if err != nil {
   159→		return err
   160→	}
   161→
   162→	if !bytes.Equal(payload.PrevRandao(), random) {
   163→		return ErrInvalidPayloadPrevRandao
   164→	}
   165→	t, err := slots.StartTime(st.GenesisTime(), st.Slot())
   166→	if err != nil {
   167→		return err
   168→	}
   169→	if payload.Timestamp() != uint64(t.Unix()) {
   170→		return ErrInvalidPayloadTimeStamp
   171→	}
   172→	return nil
   173→}
